import test from 'node:test';
import {execFileSync} from 'node:child_process';
import assert from 'node:assert/strict';
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,rmSync,existsSync,readdirSync,realpathSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {SessionManager} from '@earendil-works/pi-coding-agent';
import {CapabilityError,SourcePolicy,RuntimeCapabilityServices,TaskLedger,RecordStore,digest,type PluginContext,type JsonObject} from '@friend-pi/core';
import {SwarmController,type Graph,type MemberStart,type MemberLauncher,type StopObject} from '../src/index.js';
import {memberPrompt} from '../src/member-role.js';
import {Operations} from '../src/operations.js';
import {Budget} from '../src/budget.js';
import {SwarmStorage} from '../src/storage.js';
import {declarativeCheck} from '../src/verification.js';
const task=(id:string,mode:'read'|'write'='read',dependencies:string[]=[])=>({id,title:id,prompt:id,mode,dependencies,writeScopes:mode==='write'?[`${id}.txt`]:[]});
function fixture(host=false){const root=mkdtempSync(join(tmpdir(),'swarm-v3-')),project=join(root,'project');mkdirSync(project);writeFileSync(join(project,'original.txt'),'original');const events:{event:string;data:unknown}[]=[],services=host?new RuntimeCapabilityServices(join(root,'data')):undefined,ledger=host?new TaskLedger(join(root,'data')):undefined;const ctx:PluginContext={origin:'user',dataDir:join(root,'data'),projectDir:project,projectId:'p',sessionId:'s',runId:'run',modelId:'fixture/test',thinkingLevel:'off',agentDir:join(root,'agent'),isIdle:()=>true,history:()=>[],readSource:source=>({id:source.entryId,parentId:null,type:'message',timestamp:'',role:'user',text:'source'}),complete:async()=>{throw Error('unexpected model');},request:async(plugin,action,input)=>{if(plugin==='runtime'&&action==='task.identity'&&ledger)return ledger.resolveIdentity(input||{},ctx);if(plugin==='runtime'&&services)return services.dispatch(action,input||{}, {...ctx,origin:action==='budget.usage'?'plugin':ctx.origin});throw new CapabilityError('CAPABILITY_UNAVAILABLE','optional plugin absent');},emit:(event,data)=>events.push({event,data}),notify:()=>{},appendEntry:()=>{}};if(host)ctx.policy={v:1,revision:1,stage:'main',unsettledTools:0,canSwitchRole:false,tools:['read','write','edit','bash'],writeScopes:['.'],executionMode:'swarm',planMode:false};return {root,project,ctx,events,close(){ledger?.dispose();services?.dispose();rmSync(root,{recursive:true,force:true});}};}
const snapshot=(c:SwarmController,ctx:PluginContext)=>(c.snapshot(ctx) as {graphs:Graph[];artifacts:unknown[];operations:unknown[]});
const state=(c:SwarmController,ctx:PluginContext)=>snapshot(c,ctx).graphs[0];
async function wait(check:()=>boolean,timeout=10000){const at=Date.now();while(!check()){if(Date.now()-at>timeout)throw Error('timed out');await new Promise(r=>setTimeout(r,5));}}
function worker(options:{write?:(s:MemberStart)=>void;review?:(s:MemberStart)=>JsonObject;closeDelay?:number;usage?:(s:MemberStart)=>({entryId:string;tokens?:number})[];settledFile?:{sessionId:string;sessionFile:string}}={}){const starts:MemberStart[]=[],outputs=new Map<string,(m:any)=>void>();const launcher:MemberLauncher=(start,output,exit)=>{starts.push(start);outputs.set(start.attemptId,output);let ended=false,resolve!:(r:StopObject)=>void;const closed=new Promise<StopObject>(r=>{resolve=r;});const env=(m:any)=>output(start.v===2?{...m,v:2,protocol:2,memberId:start.memberId,generation:start.generation,attemptId:start.attemptId}:m);const finish=()=>{if(ended)return;ended=true;resolve({id:start.attemptId,kind:'member',status:'terminated',exitCode:0});exit(0);};const timer=setTimeout(()=>{if(start.mode==='write')options.write?.(start);const manager=SessionManager.create(start.cwd,start.sessionDir);manager.appendMessage({role:'user',content:memberPrompt(start),timestamp:Date.now()});env({v:1,type:'ready',sessionId:manager.getSessionId(),sessionFile:manager.getSessionFile()});if(start.frozen)env({v:1,type:'started',entryId:manager.getEntries().find(e=>e.type==='message')!.id,promptDigest:digest(memberPrompt(start)),snapshotDigest:digest(start.frozen)});for(const u of options.usage?.(start)||[])env({v:1,type:'usage',...u});env({v:1,type:'settled',summary:start.reviewResult?JSON.stringify({approved:true,findings:'objective file read checked',resultVersions:start.resultVersions,candidateDigest:start.candidateDigest,...options.review?.(start)}):`result ${start.taskId}`,sessionId:manager.getSessionId(),sessionFile:manager.getSessionFile(),...options.settledFile});setTimeout(finish,options.closeDelay||10);},5);return {closed,send:()=>{},stop:()=>{clearTimeout(timer);finish();return closed;}};};return {launcher,starts,outputs};}

test('schema3 rejects malformed contracts and coercions, and operation/CAS receipts are stable',async()=>{const f=fixture(),c=new SwarmController();try{await assert.rejects(c.dispatch('create',{goal:'x',tasks:[task('a','write')],contract:{verification:'V0'}},f.ctx),e=>e instanceof CapabilityError&&e.code==='VALIDATION_ERROR');await assert.rejects(c.dispatch('create',{goal:'x',tasks:[task('a')],automatic:'true'},f.ctx),/布尔/);const input={operationId:'create-one',goal:'x',tasks:[task('a')]},g=await c.dispatch('create',input,f.ctx) as Graph;assert.equal(g.schemaVersion,3);assert.equal((await c.dispatch('create',input,f.ctx) as Graph).id,g.id);await assert.rejects(c.dispatch('create',{...input,goal:'other'},f.ctx),e=>e instanceof CapabilityError&&e.code==='VERSION_CONFLICT');await assert.rejects(c.dispatch('configure',{graphId:g.id,maxWorkers:2,expectedRevision:999,operationId:'cas'},f.ctx),e=>e instanceof CapabilityError&&e.code==='VERSION_CONFLICT');assert.equal(snapshot(c,f.ctx).graphs.length,1);assert.ok(readdirSync(f.ctx.dataDir).some(p=>p.startsWith('swarm-pre-v3')));}finally{await c.dispose();f.close();}});

test('nonGit independent staging is checked and reviewed as one candidate; Team applies only on integrate',async()=>{const f=fixture(true),w=worker({write:s=>writeFileSync(join(s.cwd,`${s.taskId}.txt`),`${s.taskId} done`)}),c=new SwarmController(w.launcher);f.ctx.policy!.executionMode='team';f.ctx.executionMode='team';try{const g=await c.dispatch('create',{goal:'two documents',executionStyle:'team',tasks:[task('a','write'),task('b','write')],contract:{artifacts:[{id:'a',kind:'file',target:'a.txt',taskId:'a',required:true},{id:'b',kind:'file',target:'b.txt',taskId:'b',required:true}],checks:[{id:'a-exists',kind:'file.exists',target:'a.txt'},{id:'b-exists',kind:'file.exists',target:'b.txt'}]}},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>state(c,f.ctx).status==='ready');assert.equal(existsSync(join(f.project,'a.txt')),false);assert.equal(existsSync(join(f.project,'b.txt')),false);assert.notEqual(w.starts[0].cwd,w.starts[1].cwd);const review=w.starts.find(s=>s.reviewResult)!;assert.equal(readFileSync(join(review.cwd,'a.txt'),'utf8'),'a done');assert.equal(readFileSync(join(review.cwd,'b.txt'),'utf8'),'b done');await c.dispatch('integrate',{graphId:g.id,candidateDigest:state(c,f.ctx).integration!.candidateDigest},f.ctx);assert.equal(state(c,f.ctx).status,'integrated');assert.equal(readFileSync(join(f.project,'a.txt'),'utf8'),'a done');assert.equal(readFileSync(join(f.project,'b.txt'),'utf8'),'b done');assert.equal(readFileSync(join(f.project,'original.txt'),'utf8'),'original');}finally{await c.dispose();f.close();}});

test('V2 uses distinct fresh reviewer and verifier, adopting only after both exit receipts',async()=>{const f=fixture(),w=worker({closeDelay:45}),c=new SwarmController(w.launcher);try{const g=await c.dispatch('create',{goal:'high risk research',tasks:[task('a')],contract:{risk:'high',checks:[{id:'source',kind:'source.coverage',args:{sources:[{sessionId:'s',entryId:'e',hash:digest('source')}]}}]}},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>state(c,f.ctx).status==='integrated');const reviewers=w.starts.filter(s=>s.reviewResult);assert.equal(reviewers.length,2);assert.notEqual(reviewers[0].attemptId,reviewers[1].attemptId);assert.equal(reviewers[1].verificationKind,'verifier');assert.equal(state(c,f.ctx).integration!.verification!.status,'passed');assert.ok(state(c,f.ctx).integration!.verifier?.candidateDigest);}finally{await c.dispose();f.close();}});

test('source revocation between admission and native completion rejects late artifacts',async()=>{const f=fixture(),w=worker({closeDelay:100}),c=new SwarmController(w.launcher);try{const source={sessionId:'s',entryId:'e',hash:digest('source')};const g=await c.dispatch('create',{goal:'sourced',tasks:[task('a')],contract:{artifacts:[{id:'answer',kind:'answer',target:'answer',required:true,sources:[source]}]}},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>w.starts.length===1);const store=new RecordStore('host-policy',f.ctx.dataDir);new SourcePolicy(store).invalidate({projectId:'p',sources:[source],reason:'source revoked',key:'revoke'});store.close();await wait(()=>state(c,f.ctx).status==='paused');assert.equal(snapshot(c,f.ctx).artifacts.length,0);assert.notEqual(state(c,f.ctx).tasks[0].status,'completed');}finally{await c.dispose();f.close();}});

test('token usage is native-entry deduplicated, unknown remains unknown and exhausted graph stops new dispatch',async()=>{const f=fixture(),w=worker({usage:s=>s.taskId==='a'?[{entryId:'entry',tokens:4},{entryId:'entry',tokens:4},{entryId:'unknown'}]:[]}),c=new SwarmController(w.launcher);try{const g=await c.dispatch('create',{goal:'bounded',tasks:[task('a'),task('b','read',['a'])],maxWorkers:1,budget:{tokenLimit:3}},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>state(c,f.ctx).status==='paused');assert.equal(w.starts.length,1);assert.equal(state(c,f.ctx).budget?.tokenUsed,4);assert.equal(state(c,f.ctx).budget?.tokenUnknown,true);assert.equal(state(c,f.ctx).pauseReason?.code,'BUDGET_EXHAUSTED');}finally{await c.dispose();f.close();}});

test('external timeout sends once and unknown cannot be retried or replaced; reconcile needs unique readback',async()=>{const f=fixture(),store=new RecordStore('swarm',f.ctx.dataDir);new SwarmStorage(store);const ops=new Operations(store,()=>{});let sent=0;const payload={title:'one'},input={operationId:'op',graphId:'g',taskId:'t',attemptId:'a',connector:'fixture',target:'resource',action:'create',payload,payloadDigest:digest(payload),authorizationId:'auth'};try{await assert.rejects(ops.prepare(input,f.ctx),e=>e instanceof CapabilityError&&e.code==='CAPABILITY_UNAVAILABLE');f.ctx.hostOperations={prepare:async()=>({authorized:true}),dispatch:async()=>{sent++;throw Error('lost response after success');},reconcile:async()=>({status:'unknown'})};const prepared=await ops.prepare(input,f.ctx);await assert.rejects(ops.dispatch('op',prepared.revision,f.ctx),e=>e instanceof CapabilityError&&e.code==='OPERATION_UNKNOWN');assert.equal(sent,1);await assert.rejects(ops.dispatch('op',undefined,f.ctx),/不重复/);await assert.rejects(ops.prepare({...input,operationId:'different-key'},f.ctx),e=>e instanceof CapabilityError&&e.code==='OPERATION_UNKNOWN');assert.equal((await ops.reconcile('op',f.ctx)).status,'unknown');const receipt={v:1,receiptId:'r',projectId:'p',sessionId:'s',runId:'run',stage:'checked',sources:[],dependencies:[],contentHash:digest('one'),at:new Date().toISOString()};f.ctx.hostOperations.reconcile=async()=>({status:'confirmed',externalId:'unique-one',receipt,readback:receipt});assert.equal((await ops.reconcile('op',f.ctx)).status,'confirmed');assert.equal(sent,1);await assert.rejects(ops.prepare({...input,status:'confirmed'},f.ctx),e=>e instanceof CapabilityError&&e.code==='PERMISSION_DENIED');}finally{store.close();f.close();}});

test('declarative JSON/CSV/source checks use actual files and reject malformed contracts',()=>{const f=fixture();try{writeFileSync(join(f.project,'result.json'),JSON.stringify({count:2}));assert.equal(declarativeCheck({id:'json',kind:'json.schema',target:'result.json',args:{schema:{type:'object',required:['count'],additionalProperties:false,properties:{count:{type:'integer'}}}}},f.project,f.ctx).exitCode,0);writeFileSync(join(f.project,'data.csv'),'name,value\n"a,b",2\n');assert.equal(declarativeCheck({id:'csv',kind:'csv.contract',target:'data.csv',args:{headers:['name','value'],minRows:1}},f.project,f.ctx).exitCode,0);writeFileSync(join(f.project,'data.csv'),'name,value\n"unterminated,2');assert.equal(declarativeCheck({id:'bad',kind:'csv.contract',target:'data.csv',args:{headers:['name','value']}},f.project,f.ctx).exitCode,1);}finally{f.close();}});

test('outbox persists failed notifications and retries the same event identity without mutation',()=>{const f=fixture(),store=new RecordStore('swarm',f.ctx.dataDir),storage=new SwarmStorage(store);let calls=0;const ids:string[]=[];f.ctx.emit=(_event,data)=>{ids.push((data as {eventId:string}).eventId);if(calls++===0)throw Error('disconnected renderer');};try{storage.enqueue('swarm.artifact.changed','g',1,f.ctx,{artifactId:'a'});assert.equal(store.db.prepare('SELECT delivered_at FROM swarm_outbox').get()!.delivered_at,null);storage.flush(f.ctx);assert.equal(ids.length,2);assert.equal(ids[0],ids[1]);assert.ok(store.db.prepare('SELECT delivered_at FROM swarm_outbox').get()!.delivered_at);}finally{store.close();f.close();}});

test('same failed evidence and unchanged outputs stop repair after one wave; separate task failures cannot exceed graph repair2',async()=>{const f=fixture(),w=worker({review:()=>({approved:false,findings:'unchanged oracle failure',taskIds:['a']})}),c=new SwarmController(w.launcher);try{const g=await c.dispatch('create',{goal:'bounded repair',tasks:[task('a'),task('downstream','read',['a']),task('unrelated')],contract:{verification:'V1'}},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>state(c,f.ctx).status==='paused'&&state(c,f.ctx).reworkRound===1&&w.starts.filter(s=>s.reviewResult).length===2);assert.equal(state(c,f.ctx).pauseReason?.code,'BUDGET_EXHAUSTED');assert.equal(w.starts.filter(s=>s.taskId==='unrelated').length,1);assert.equal(w.starts.filter(s=>s.taskId==='a').length,2);assert.equal(w.starts.filter(s=>s.taskId==='downstream').length,2);}finally{await c.dispose();f.close();}});

test('candidate files changed during review invalidate the old approval and preserve original project',async()=>{const f=fixture(),w=worker({write:s=>writeFileSync(join(s.cwd,'a.txt'),'candidate'),closeDelay:70}),c=new SwarmController(w.launcher);try{const g=await c.dispatch('create',{goal:'candidate binding',tasks:[task('a','write')],contract:{artifacts:[{id:'a',kind:'file',target:'a.txt',required:true}],checks:[{id:'a',kind:'file.exists',target:'a.txt'}]}},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>w.starts.some(s=>s.reviewResult));writeFileSync(join(w.starts.find(s=>s.reviewResult)!.cwd,'a.txt'),'tampered after checks');await wait(()=>state(c,f.ctx).status==='paused');assert.equal(existsSync(join(f.project,'a.txt')),false);assert.notEqual(state(c,f.ctx).integration!.verification!.status,'passed');}finally{await c.dispose();f.close();}});

test('partial nonGit apply keeps per-file receipts, preserves conflicting bytes and never replays unknown item',async()=>{const f=fixture(),w=worker({write:s=>writeFileSync(join(s.cwd,`${s.taskId}.txt`),`${s.taskId} result`)}),c=new SwarmController(w.launcher);f.ctx.executionMode='team';try{const g=await c.dispatch('create',{goal:'partial apply',executionStyle:'team',tasks:[task('a','write'),task('b','write')],contract:{artifacts:[{id:'a',kind:'file',target:'a.txt',taskId:'a',required:true},{id:'b',kind:'file',target:'b.txt',taskId:'b',required:true}],checks:[{id:'a',kind:'file.exists',target:'a.txt'},{id:'b',kind:'file.exists',target:'b.txt'}]}},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>state(c,f.ctx).status==='ready');const {Artifacts}=await import('../src/artifacts.js'),store=new RecordStore('swarm',f.ctx.dataDir),artifacts=new Artifacts(store,()=>{});let checked=0;try{await assert.rejects(artifacts.apply(state(c,f.ctx),f.ctx,async()=>{if(++checked===2)writeFileSync(join(f.project,'b.txt'),'outside write');}),e=>e instanceof CapabilityError&&e.code==='VERSION_CONFLICT');assert.equal(readFileSync(join(f.project,'a.txt'),'utf8'),'a result');assert.equal(readFileSync(join(f.project,'b.txt'),'utf8'),'outside write');const statuses=store.db.prepare('SELECT status FROM swarm_file_applications ORDER BY target').all().map(r=>r.status);assert.deepEqual(statuses,['applied','unknown']);await assert.rejects(artifacts.apply(state(c,f.ctx),f.ctx,async()=>{}),e=>e instanceof CapabilityError&&e.code==='OPERATION_UNKNOWN');assert.equal(readFileSync(join(f.project,'b.txt'),'utf8'),'outside write');}finally{store.close();}}finally{await c.dispose();f.close();}});

test('cold recovery keeps provisioning unknown and never creates a replacement native task',async()=>{const f=fixture(),w=worker(),c=new SwarmController(w.launcher);try{const g=await c.dispatch('create',{goal:'crashed provisioning',tasks:[task('a')]},f.ctx) as Graph;const store=new RecordStore('swarm',f.ctx.dataDir),row=store.get<Graph>(`graph:p:${g.id}`)!;row.value.status='running';row.value.executionOwner={pid:2147483647,runtime:'dead'};row.value.tasks[0].status='running';row.value.tasks[0].currentAttempt='lost';row.value.attempts.push({id:'lost',taskId:'a',number:1,resultRevision:1,status:'running',cwd:f.project,mode:'read',ownerPid:2147483647,ownerRuntime:'dead',startedAt:new Date().toISOString(),writeScopes:[],memberId:g.tasks[0].memberId,generation:1});store.put(row.key,row.value,row.revision);store.close();const recovered=new SwarmController(w.launcher);try{assert.equal(state(recovered,f.ctx).status,'paused');assert.equal(state(recovered,f.ctx).tasks[0].status,'unknown');assert.equal(w.starts.length,0);assert.equal(state(recovered,f.ctx).pauseReason?.code,'OPERATION_UNKNOWN');}finally{await recovered.dispose();}}finally{await c.dispose();f.close();}});

test('optional Memory supplies complete conditions and exact dependencies; disabled capability is a transparent fallback',async()=>{const f=fixture(),w=worker(),c=new SwarmController(w.launcher),store=new RecordStore('host-policy',f.ctx.dataDir);const content='Stable project convention',hash=digest(content);new SourcePolicy(store).publishDependency({projectId:'p',capability:'memory',id:'m',version:2,hash,valid:true});f.ctx.request=async(plugin,action)=>{if(plugin==='memory'&&action==='select')return {records:[{id:'m',revision:2,hash,content,sources:[],conditions:['Only in fixture project']}],directory:[]};throw new CapabilityError('CAPABILITY_UNAVAILABLE','optional plugin absent');};try{const g=await c.dispatch('create',{goal:'memory adoption',tasks:[task('a')]},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>state(c,f.ctx).status==='integrated');assert.match(w.starts[0].prompt,/Stable project convention/);assert.match(w.starts[0].prompt,/Only in fixture project/);assert.deepEqual(state(c,f.ctx).attempts[0].frozen!.memoryRefs,[{capability:'memory',id:'m',version:2,hash,relation:'adopted'}]);new SourcePolicy(store).invalidate({projectId:'p',dependencies:[{capability:'memory',id:'m',version:2,hash,relation:'adopted'}],reason:'forgotten',key:'forget'});await assert.rejects(c.dispatch('shared.write',{graphId:g.id,name:'stale',content:'stale result',expectedRevision:0},f.ctx),e=>e instanceof CapabilityError&&e.code==='SOURCE_UNAVAILABLE');}finally{store.close();await c.dispose();f.close();}});

test('controller external operation stages share one original identity across prepare/dispatch/replay and retain host receipts',async()=>{const f=fixture(),w=worker(),c=new SwarmController(w.launcher);let calls=0;const receipt={v:1,receiptId:'host-receipt',projectId:'p',sessionId:'s',runId:'run',stage:'checked',sources:[],dependencies:[],contentHash:digest('actual content'),at:new Date().toISOString()};f.ctx.hostOperations={prepare:async()=>({authorized:true}),dispatch:async()=>{calls++;return {status:'confirmed',receipt,readback:receipt,resultDigest:receipt.contentHash};},reconcile:async()=>({status:'confirmed',receipt,readback:receipt,resultDigest:receipt.contentHash})};try{const g=await c.dispatch('create',{goal:'controlled external',deferPreparation:true,tasks:[task('a')]},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>state(c,f.ctx).status==='completed');const payload={content:'actual content'},input={graphId:g.id,taskId:'a',attemptId:state(c,f.ctx).tasks[0].currentAttempt,operationId:'external-one',connector:'fixture',target:'fixture://approved-target',action:'create',payload,payloadDigest:digest(payload),authorizationId:'test-auth'};const prepared=await c.dispatch('operation.prepare',input,f.ctx) as {revision:number};const result=await c.dispatch('operation.dispatch',{graphId:g.id,operationId:'external-one',revision:prepared.revision},f.ctx) as {status:string};assert.equal(result.status,'confirmed');const replay=await c.dispatch('operation.dispatch',{graphId:g.id,operationId:'external-one'},f.ctx) as {status:string};assert.equal(replay.status,'confirmed');assert.equal(calls,1);}finally{await c.dispose();f.close();}});

test('failed additive migration rolls back new schema, preserves old records and keeps a SQLite snapshot',()=>{const f=fixture(),store=new RecordStore('swarm',f.ctx.dataDir);store.put('legacy',{schemaVersion:2,summary:'preserved'});const original=store.db.exec.bind(store.db);store.db.exec=sql=>{if(sql.includes('CREATE TABLE IF NOT EXISTS swarm_schema_migrations')){original('CREATE TABLE migration_partial(value TEXT)');throw Error('injected migration failure');}return original(sql);};try{assert.throws(()=>new SwarmStorage(store),/injected migration/);assert.equal(store.get<{summary:string}>('legacy')!.value.summary,'preserved');assert.equal(store.db.prepare("SELECT 1 FROM sqlite_master WHERE name='migration_partial'").get(),undefined);assert.equal(store.db.prepare("SELECT 1 FROM sqlite_master WHERE name='swarm_schema_migrations'").get(),undefined);assert.ok(readdirSync(f.ctx.dataDir).some(file=>file.startsWith('swarm-pre-v3-')&&file.endsWith('.sqlite')));}finally{store.close();f.close();}});

test('a legacy SQLite writer can read upgraded UNKNOWN but cannot claim it or overwrite operation receipts',async()=>{const f=fixture(),c=new SwarmController();try{const g=await c.dispatch('create',{goal:'old writer boundary',tasks:[task('a')]},f.ctx) as Graph;const modern=new RecordStore('swarm',f.ctx.dataDir),row=modern.get<Graph>(`graph:p:${g.id}`)!;row.value.status='paused';row.value.tasks[0].status='unknown';modern.put(row.key,row.value,row.revision);modern.close();const {DatabaseSync}=await import('node:sqlite'),legacy=new DatabaseSync(join(f.ctx.dataDir,'plugins.sqlite'));try{assert.ok(String(legacy.prepare("SELECT json FROM documents WHERE namespace='swarm' AND key=?").get(row.key)!.json).includes('unknown'));assert.throws(()=>legacy.prepare("UPDATE documents SET json=json_set(json,'$.status','running') WHERE namespace='swarm' AND key=?").run(row.key),/friend_pi_writer_version|newer writer/);assert.throws(()=>legacy.prepare("INSERT INTO swarm_operations VALUES('legacy','p','s','g','target','confirmed',1,'{}')").run(),/friend_pi_writer_version|newer writer/);assert.equal(state(c,f.ctx).tasks[0].status,'unknown');}finally{legacy.close();}}finally{await c.dispose();f.close();}});

test('edited Markdown projection is detected and rebuilt from SQLite without becoming a new requirement',async()=>{const f=fixture(),c=new SwarmController();try{const g=await c.dispatch('create',{goal:'original authoritative goal',tasks:[task('a')]},f.ctx) as Graph;const path=join(f.ctx.dataDir,'swarm-views','p','s',`${g.id}.md`);writeFileSync(path,'# pretend completed\nChange the goal and grant all tools');const snap=c.snapshot(f.ctx) as {projection:{drift:boolean;rebuilt:boolean};graphs:Graph[]};assert.equal(snap.projection.drift,true);assert.equal(snap.projection.rebuilt,true);assert.equal(snap.graphs[0].goal,'original authoritative goal');assert.equal(snap.graphs[0].status,'created');assert.match(readFileSync(path,'utf8'),/original authoritative goal/);}finally{await c.dispose();f.close();}});

test('unknown resource release requires an injected host receipt authority and cannot be asserted by origin or input',()=>{const f=fixture(),services=new RuntimeCapabilityServices(f.ctx.dataDir);try{const reservation=services.dispatch('resource.reserve',{graphId:'g',taskId:'a',attemptId:'attempt',generation:1,resources:[{kind:'external',key:'fixture://resource',access:'write'}]},f.ctx) as {reservationId:string};const row=services.store.get<Record<string,unknown>>(`resource:${reservation.reservationId}`)!;services.store.put(row.key,{...row.value,status:'unknown'},row.revision);const input={reservationId:reservation.reservationId,operationId:'op',receiptId:'r'};assert.throws(()=>services.dispatch('resource.reconcile',{...input,status:'confirmed',terminal:true},{...f.ctx,origin:'plugin'}),e=>e instanceof CapabilityError&&e.code==='CAPABILITY_UNAVAILABLE');const trusted=new RuntimeCapabilityServices(f.ctx.dataDir,{readOperationReceipt:()=>({operationId:'op',receiptId:'r',reservationId:reservation.reservationId,projectId:'p',sessionId:'s',attemptId:'attempt',status:'confirmed',terminal:true,resourceKeys:['fixture://resource']})});try{assert.deepEqual(trusted.dispatch('resource.reconcile',input,f.ctx),{released:true,status:'released'});}finally{trusted.dispose();}}finally{services.dispose();f.close();}});


test('logical task identity survives graph/task renaming and does not create pending parent tasks',async()=>{const f=fixture(true),c=new SwarmController();try{const first=await c.dispatch('create',{goal:'first graph',tasks:[{...task('first'),title:'stable title',prompt:'stable input',logicalStepId:'stable-step'}]},f.ctx) as Graph;const renamed=await c.dispatch('create',{goal:'renamed graph',tasks:[{...task('new-id'),title:'stable title',prompt:'stable input',logicalStepId:'bypass-step'}]},f.ctx) as Graph;assert.equal(renamed.tasks[0].logicalStepId,first.tasks[0].logicalStepId);const ledger=new TaskLedger(f.ctx.dataDir);try{assert.equal(ledger.list(f.ctx).length,0);}finally{ledger.dispose();}}finally{await c.dispose();f.close();}});

test('native child registry retains parent project identity and refuses an unrelated session file',async()=>{const f=fixture(),w=worker({write:s=>writeFileSync(join(s.cwd,'a.txt'),'output')}),c=new SwarmController(w.launcher);try{const g=await c.dispatch('create',{goal:'registered child',tasks:[task('a','write')],contract:{artifacts:[{id:'a',kind:'file',target:'a.txt',required:true}],checks:[{id:'a',kind:'file.exists',target:'a.txt'}]}},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>state(c,f.ctx).status==='integrated');const current=state(c,f.ctx).attempts[0],registry=new RecordStore('sessions',f.ctx.dataDir);try{const registered=registry.get<{path:string;projectDir:string}>(current.sessionId!)!.value;assert.equal(registered.projectDir,realpathSync(f.project));assert.equal(registered.path,realpathSync(current.sessionFile!));assert.notEqual(JSON.parse(readFileSync(current.sessionFile!,'utf8').split('\n')[0]).cwd,f.project);}finally{registry.close();}}finally{await c.dispose();f.close();}
 const other=fixture(),outside=SessionManager.create(other.project,join(other.root,'foreign'));outside.appendMessage({role:'user',content:'unrelated',timestamp:Date.now()});const bad=worker({settledFile:{sessionId:outside.getSessionId(),sessionFile:outside.getSessionFile()!}}),controller=new SwarmController(bad.launcher);try{const g=await controller.dispatch('create',{goal:'reject foreign child',tasks:[task('a')]},other.ctx) as Graph;await controller.dispatch('start',{graphId:g.id},other.ctx);await wait(()=>state(controller,other.ctx).status==='paused');assert.notEqual(state(controller,other.ctx).tasks[0].status,'completed');const registry=new RecordStore('sessions',other.ctx.dataDir);try{assert.equal(registry.get(outside.getSessionId()),undefined);}finally{registry.close();}}finally{await controller.dispose();other.close();}});

test('failed complete persists observed tokens once and emits one parent usage receipt before release',async()=>{const f=fixture(true),store=new RecordStore('swarm',f.ctx.dataDir);new SwarmStorage(store);const budget=new Budget(store);f.ctx.complete=async(_prompt,options)=>{options?.onUsage?.({callId:options.callId!,tokens:7});throw Error('provider failed after token usage');};try{const captured=await budget.capture('g',undefined,1,f.ctx);await assert.rejects(budget.complete(captured,'g','plan',f.ctx,'request'),/provider failed/);const rows=store.db.prepare('SELECT * FROM swarm_budget_usage').all();assert.equal(rows.length,1);assert.equal(rows[0].tokens,7);const usage=f.events.filter(event=>event.event==='runtime.model-usage');assert.equal(usage.length,1);assert.equal((usage[0].data as {tokens:number}).tokens,7);const saved=await f.ctx.request('runtime','budget.read',{budgetId:captured.budgetId}) as {tokenUsed:number;tokenReserved:number};assert.equal(saved.tokenUsed,7);assert.equal(saved.tokenReserved,0);}finally{store.close();f.close();}});

test('managed live child renews resources during a long model call and stops on lost lease',async t=>{const f=fixture(true);let stops=0,checks=0,lose=false;const original=f.ctx.request;f.ctx.request=async(plugin,action,input,timeout)=>{if(plugin==='runtime'&&action==='resource.check'){checks++;if(lose)throw new CapabilityError('OPERATION_UNKNOWN','expired lease');}return original(plugin,action,input,timeout);};const launcher:MemberLauncher=(start,output,exit)=>{let close!:(receipt:StopObject)=>void;const closed=new Promise<StopObject>(resolve=>{close=resolve;});queueMicrotask(()=>{const manager=SessionManager.create(start.cwd,start.sessionDir);manager.appendMessage({role:'user',content:memberPrompt(start),timestamp:Date.now()});output({v:2,protocol:2,memberId:start.memberId!,generation:start.generation!,attemptId:start.attemptId,type:'ready',sessionId:manager.getSessionId(),sessionFile:manager.getSessionFile()});output({v:2,protocol:2,memberId:start.memberId!,generation:start.generation!,attemptId:start.attemptId,type:'started',entryId:manager.getEntries().find(e=>e.type==='message')!.id,promptDigest:digest(memberPrompt(start)),snapshotDigest:digest(start.frozen)});});return {closed,send:()=>{},stop:async()=>{stops++;const receipt:StopObject={id:start.attemptId,kind:'member',status:'terminated',exitCode:0};close(receipt);exit(0);return receipt;}};};const c=new SwarmController(launcher);t.mock.timers.enable({apis:['setInterval']});try{const g=await c.dispatch('create',{goal:'long-running child',tasks:[task('a','write')]},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>!!state(c,f.ctx).attempts[0]?.sessionId);const before=checks;t.mock.timers.tick(20000);await wait(()=>checks>before);await new Promise(resolve=>setImmediate(resolve));assert.equal(state(c,f.ctx).status,'running');lose=true;t.mock.timers.tick(20000);await wait(()=>state(c,f.ctx).status==='paused');assert.ok(stops>0);assert.equal(state(c,f.ctx).pauseReason?.code,'OPERATION_UNKNOWN');}finally{t.mock.timers.reset();await c.dispose();f.close();}});


for(const corruptDependency of [false,true])test(`nonGit dependent writers use inherited input baseline and ${corruptDependency?'reject an out-of-scope dependency edit':'apply both scoped outputs'}`,async()=>{
 const f=fixture(),w=worker({write:start=>{if(start.taskId==='a')writeFileSync(join(start.cwd,'a.txt'),'producer output');else{assert.equal(readFileSync(join(start.cwd,'a.txt'),'utf8'),'producer output');if(corruptDependency)writeFileSync(join(start.cwd,'a.txt'),'out of scope');writeFileSync(join(start.cwd,'b.txt'),'consumer read producer output');}}}),c=new SwarmController(w.launcher);f.ctx.executionMode='team';
 try{const graph=await c.dispatch('create',{goal:'dependent nonGit writers',executionStyle:'team',tasks:[task('a','write'),task('b','write',['a'])],contract:{artifacts:[{id:'a-file',kind:'file',target:'a.txt',taskId:'a',required:true},{id:'b-file',kind:'file',target:'b.txt',taskId:'b',required:true}],checks:[{id:'a',kind:'file.hash',target:'a.txt',args:{sha256:digest('producer output')}},{id:'b',kind:'file.hash',target:'b.txt',args:{sha256:digest('consumer read producer output')}}]}},f.ctx) as Graph;await c.dispatch('start',{graphId:graph.id},f.ctx);await wait(()=>['ready','paused'].includes(state(c,f.ctx).status));const current=state(c,f.ctx);assert.equal(existsSync(join(f.project,'a.txt')),false);assert.equal(existsSync(join(f.project,'b.txt')),false);assert.equal(readFileSync(join(current.attempts[0].cwd,'a.txt'),'utf8'),'producer output');if(corruptDependency){assert.equal(current.status,'paused');assert.match(current.error!,/写入范围外/);assert.notEqual(current.tasks[1].status,'completed');}else{assert.equal(current.status,'ready',current.error);assert.equal(current.attempts[1].targetBaselines?.['a.txt'],'missing');assert.equal(current.attempts[1].inputBaselines?.['a.txt'],digest('producer output'));await c.dispatch('integrate',{graphId:graph.id,candidateDigest:current.integration!.candidateDigest},f.ctx);assert.equal(state(c,f.ctx).status,'integrated');assert.equal(readFileSync(join(f.project,'a.txt'),'utf8'),'producer output');assert.equal(readFileSync(join(f.project,'b.txt'),'utf8'),'consumer read producer output');const store=new RecordStore('swarm',f.ctx.dataDir);try{assert.equal(store.db.prepare("SELECT COUNT(*) AS n FROM swarm_file_applications WHERE status='applied'").get()!.n,2);}finally{store.close();}}}finally{await c.dispose();f.close();}
});


test('failed child with UNKNOWN stop keeps handle, resource and budget until a real close receipt',async()=>{const f=fixture(true);let close!:(receipt:StopObject)=>void,starts=0;const releases:string[]=[];const request=f.ctx.request;f.ctx.request=async(plugin,action,input,timeout)=>{if(['resource.release','budget.release'].includes(action))releases.push(action);return request(plugin,action,input,timeout);};const launcher:MemberLauncher=(start,output)=>{starts++;const closed=new Promise<StopObject>(resolve=>{close=resolve;});setImmediate(()=>output({v:2,protocol:2,memberId:start.memberId!,generation:start.generation!,attemptId:start.attemptId,type:'failed',error:'source invalidated while child still running'}));return {closed,send:()=>{},stop:async()=>({id:start.attemptId,kind:'member',status:'unknown'})};};const c=new SwarmController(launcher);try{const graph=await c.dispatch('create',{goal:'unknown child',tasks:[task('a','write')]},f.ctx) as Graph;await c.dispatch('start',{graphId:graph.id},f.ctx);await wait(()=>state(c,f.ctx).status==='paused'&&(c.snapshot(f.ctx) as {teammates:{stopReceipt?:StopObject}[]}).teammates[0]?.stopReceipt?.status==='unknown');assert.equal(releases.length,0);const attempt=state(c,f.ctx).attempts[0];await assert.rejects(f.ctx.request('runtime','resource.reserve',{graphId:'other',taskId:'other',attemptId:'other',generation:1,resources:[{kind:'path',key:'a.txt',access:'write'}]}),e=>e instanceof CapabilityError&&e.code==='VERSION_CONFLICT');assert.equal(starts,1);close({id:attempt.id,kind:'member',status:'terminated',exitCode:0});await wait(()=>releases.includes('resource.release')&&releases.includes('budget.release'));const reserved=await f.ctx.request('runtime','resource.reserve',{graphId:'after-close',taskId:'other',attemptId:'after-close',generation:1,resources:[{kind:'path',key:'a.txt',access:'write'}]}) as {reservationId:string};await f.ctx.request('runtime','resource.release',{reservationId:reserved.reservationId});}finally{if(close)close({id:state(c,f.ctx).attempts[0]?.id||'none',kind:'member',status:'terminated',exitCode:0});await c.dispose();f.close();}});

test('native schema3 logical repair quota persists across different graphs and controllers',async()=>{const f=fixture(),w=worker({review:()=>({approved:false,findings:'needs a changed method',taskIds:[]})});let c=new SwarmController(w.launcher);try{for(let i=0;i<3;i++){const graph=await c.dispatch('create',{goal:`graph ${i}`,contract:{verification:'V1'},tasks:[{...task('a'),title:'same logical task',prompt:'same original input',logicalStepId:'logical-shared'}]},f.ctx) as Graph;await c.dispatch('start',{graphId:graph.id},f.ctx);await wait(()=>((c.snapshot(f.ctx) as {graphs:Graph[]}).graphs.find(g=>g.id===graph.id)!.status==='paused'));if(i<2){await c.dispatch('rework',{graphId:graph.id,taskIds:['a'],reason:'changed method',prompts:{a:`explicit method ${i}`}},f.ctx);await wait(()=>((c.snapshot(f.ctx) as {graphs:Graph[]}).graphs.find(g=>g.id===graph.id)!.status==='paused'));await c.dispose();c=new SwarmController(w.launcher);}else{await assert.rejects(c.dispatch('rework',{graphId:graph.id,taskIds:['a'],reason:'third graph same step',prompts:{a:'third method'}},f.ctx),e=>e instanceof CapabilityError&&e.code==='BUDGET_EXHAUSTED');assert.equal((c.snapshot(f.ctx) as {graphs:Graph[]}).graphs.find(g=>g.id===graph.id)!.reworkRound,0);}}}finally{await c.dispose();f.close();}});

for(const targetDrift of [false,true])test(`nonGit serial writers select the final topological target and ${targetDrift?'retain a drifted original':'apply it once while preserving intermediate artifacts'}`,async()=>{const f=fixture(),w=worker({write:start=>{if(start.taskId==='z-first')writeFileSync(join(start.cwd,'shared.txt'),'A intermediate');else{assert.equal(readFileSync(join(start.cwd,'shared.txt'),'utf8'),'A intermediate');writeFileSync(join(start.cwd,'shared.txt'),'B final');}}}),c=new SwarmController(w.launcher);writeFileSync(join(f.project,'shared.txt'),'original baseline');f.ctx.executionMode='team';try{const graph=await c.dispatch('create',{goal:'serial same-file writers',executionStyle:'team',tasks:[{...task('z-first','write'),writeScopes:['shared.txt']},{...task('a-last','write',['z-first']),writeScopes:['shared.txt']}],contract:{artifacts:[{id:'zz-initial',kind:'file',target:'shared.txt',taskId:'z-first',required:true},{id:'aa-final',kind:'file',target:'shared.txt',taskId:'a-last',required:true}],checks:[{id:'final',kind:'file.hash',target:'shared.txt',args:{sha256:digest('B final')}}]}},f.ctx) as Graph;await c.dispatch('start',{graphId:graph.id},f.ctx);await wait(()=>['ready','paused'].includes(state(c,f.ctx).status));const current=state(c,f.ctx);assert.equal(current.status,'ready',current.error);const artifacts=await c.dispatch('artifact.list',{graphId:graph.id},f.ctx) as {artifacts:{artifactId:string;stagingPath:string;digest:string}[]};const items=Array.isArray(artifacts)?artifacts:artifacts.artifacts;assert.ok(items.some(a=>a.artifactId==='zz-initial'&&readFileSync(a.stagingPath,'utf8')==='A intermediate'));assert.equal(readFileSync(join(f.project,'shared.txt'),'utf8'),'original baseline');if(targetDrift){writeFileSync(join(f.project,'shared.txt'),'user draft');await assert.rejects(c.dispatch('integrate',{graphId:graph.id,candidateDigest:current.integration!.candidateDigest},f.ctx),e=>e instanceof CapabilityError&&e.code==='VERSION_CONFLICT');assert.equal(readFileSync(join(f.project,'shared.txt'),'utf8'),'user draft');}else{await c.dispatch('integrate',{graphId:graph.id,candidateDigest:current.integration!.candidateDigest},f.ctx);assert.equal(readFileSync(join(f.project,'shared.txt'),'utf8'),'B final');const store=new RecordStore('swarm',f.ctx.dataDir);try{const rows=store.db.prepare('SELECT baseline,backup,status FROM swarm_file_applications').all();assert.equal(rows.length,1);assert.equal(rows[0].baseline,digest('original baseline'));assert.equal(rows[0].status,'applied');assert.equal(readFileSync(String(rows[0].backup),'utf8'),'original baseline');}finally{store.close();}}}finally{await c.dispose();f.close();}});


test('a launcher throw after entering child creation cannot claim no-child or release reservations during dispose',async()=>{const f=fixture(true),releases:string[]=[];const request=f.ctx.request;f.ctx.request=async(plugin,action,input,timeout)=>{if(['resource.release','budget.release'].includes(action))releases.push(action);return request(plugin,action,input,timeout);};const c=new SwarmController(()=>{throw Error('adapter threw after its creation boundary');});try{const graph=await c.dispatch('create',{goal:'uncertain launcher',tasks:[task('a','write')]},f.ctx) as Graph;await c.dispatch('start',{graphId:graph.id},f.ctx);await wait(()=>state(c,f.ctx).attempts[0]?.exitReceipt?.status==='unknown');assert.equal(state(c,f.ctx).attempts[0].childCreationStarted,true);assert.equal(state(c,f.ctx).attempts[0].exitReceipt?.status,'unknown');assert.equal(releases.length,0);await c.dispose();assert.equal(releases.length,0);}finally{await c.dispose();f.close();}});


test('independent nonGit writers cannot reserve the same path without a dependency edge',async()=>{const f=fixture(),w=worker(),c=new SwarmController(w.launcher);try{await assert.rejects(c.dispatch('create',{goal:'parallel conflicting targets',tasks:[{...task('a','write'),writeScopes:['shared.txt']},{...task('b','write'),writeScopes:['shared.txt']}]},f.ctx),e=>e instanceof CapabilityError&&e.code==='VALIDATION_ERROR');assert.equal(w.starts.length,0);assert.equal(snapshot(c,f.ctx).graphs.length,0);}finally{await c.dispose();f.close();}});


test('verified prelaunch rejection releases the resource and budget without claiming an unknown child',async()=>{const f=fixture(true),calls:string[]=[];const request=f.ctx.request;f.ctx.request=async(plugin,action,input,timeout)=>{if(['resource.release','budget.release'].includes(action))calls.push(action);return request(plugin,action,input,timeout);};const c=new SwarmController(()=>{throw Error('must not reach launcher');});try{const graph=await c.dispatch('create',{goal:'bad role before child creation',tasks:[{...task('a','write'),roleId:'missing-role'}]},f.ctx) as Graph;await c.dispatch('start',{graphId:graph.id},f.ctx);await wait(()=>state(c,f.ctx).attempts[0]?.reservationsReleased===true);const attempt=state(c,f.ctx).attempts[0];assert.equal(attempt.childCreationStarted,undefined);assert.equal(attempt.exitReceipt?.status,'terminated');assert.ok(calls.includes('resource.release'));assert.ok(calls.includes('budget.release'));}finally{await c.dispose();f.close();}});

test('serial same-target writers reject original project drift between their staging snapshots',async()=>{const f=fixture(),w=worker({write:start=>{if(start.taskId==='a'){writeFileSync(join(start.cwd,'shared.txt'),'A stage');writeFileSync(join(f.project,'shared.txt'),'external draft');}else writeFileSync(join(start.cwd,'shared.txt'),'B final');}}),c=new SwarmController(w.launcher);writeFileSync(join(f.project,'shared.txt'),'original');f.ctx.executionMode='team';try{const graph=await c.dispatch('create',{goal:'target drift between attempts',executionStyle:'team',tasks:[{...task('a','write'),writeScopes:['shared.txt']},{...task('b','write',['a']),writeScopes:['shared.txt']}],contract:{checks:[{id:'exists',kind:'file.exists',target:'shared.txt'}]}},f.ctx) as Graph;await c.dispatch('start',{graphId:graph.id},f.ctx);await wait(()=>state(c,f.ctx).status==='paused');assert.match(state(c,f.ctx).error!,/原项目目标已变化/);assert.equal(readFileSync(join(f.project,'shared.txt'),'utf8'),'external draft');assert.ok(state(c,f.ctx).attempts.every(attempt=>attempt.status==='completed'));}finally{await c.dispose();f.close();}});

for(const drift of [false,true])test(`dirty isolated snapshot preserves staged/unstaged/untracked state and ${drift?'rejects target drift':'applies only task delta'}`,async()=>{
 const f=fixture(),git=(...args:string[])=>execFileSync('git',['-C',f.project,...args],{encoding:'utf8'}).trim();git('init','-q');git('add','original.txt');git('-c','user.name=Fixture','-c','user.email=fixture@local','commit','-qm','baseline');writeFileSync(join(f.project,'original.txt'),'staged');git('add','original.txt');writeFileSync(join(f.project,'original.txt'),'unstaged');writeFileSync(join(f.project,'untracked.txt'),'original untracked');const index=git('show',':original.txt'),head=git('rev-parse','HEAD');
 const w=worker({write:s=>{assert.equal(readFileSync(join(s.cwd,'original.txt'),'utf8'),'unstaged');assert.equal(readFileSync(join(s.cwd,'untracked.txt'),'utf8'),'original untracked');writeFileSync(join(s.cwd,'a.txt'),'task delta');}}),c=new SwarmController(w.launcher);f.ctx.executionMode='team';
 try{const g=await c.dispatch('create',{goal:'dirty snapshot',executionStyle:'team',executionPolicy:{v:1,workspace:'isolated',review:'none',dirtyBaseline:'snapshot'},tasks:[task('a','write')],contract:{checks:[{id:'a',kind:'file.exists',target:'a.txt'}]}},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>['ready','paused'].includes(state(c,f.ctx).status));assert.equal(state(c,f.ctx).status,'ready',state(c,f.ctx).error);assert.equal(state(c,f.ctx).integration?.reviewStatus,'not_requested');assert.equal(w.starts.some(s=>s.reviewResult),false);assert.notEqual(w.starts[0].cwd,f.project);assert.equal(state(c,f.ctx).attempts[0].commit,undefined);assert.equal(git('show',':original.txt'),index);assert.equal(git('rev-parse','HEAD'),head);assert.equal(existsSync(join(f.project,'a.txt')),false);
 if(drift)writeFileSync(join(f.project,'a.txt'),'user concurrent draft');const apply=c.dispatch('integrate',{graphId:g.id,candidateDigest:state(c,f.ctx).integration!.candidateDigest},f.ctx);if(drift)await assert.rejects(apply,e=>e instanceof CapabilityError&&e.code==='VERSION_CONFLICT');else await apply;assert.equal(readFileSync(join(f.project,'a.txt'),'utf8'),drift?'user concurrent draft':'task delta');assert.equal(readFileSync(join(f.project,'original.txt'),'utf8'),'unstaged');assert.equal(readFileSync(join(f.project,'untracked.txt'),'utf8'),'original untracked');assert.equal(git('show',':original.txt'),index);assert.equal(git('rev-parse','HEAD'),head);
 }finally{await c.dispose();f.close();}
});

test('shared writers execute in original cwd, preserve Git index/head and retain immutable intermediate artifacts',async()=>{
 const f=fixture(true),git=(...args:string[])=>execFileSync('git',['-C',f.project,...args],{encoding:'utf8'}).trim();git('init','-q');git('add','original.txt');git('-c','user.name=Fixture','-c','user.email=fixture@local','commit','-qm','baseline');const head=git('rev-parse','HEAD');writeFileSync(join(f.project,'original.txt'),'user draft');const w=worker({write:s=>{assert.equal(s.cwd,f.project);if(s.taskId==='b')assert.equal(readFileSync(join(s.cwd,'a.txt'),'utf8'),'first');writeFileSync(join(s.cwd,'a.txt'),s.taskId==='a'?'first':'final');}}),c=new SwarmController(w.launcher);
 try{const g=await c.dispatch('create',{goal:'shared',executionPolicy:{v:1,workspace:'shared',review:'none',dirtyBaseline:'snapshot'},tasks:[task('a','write'),{...task('b','write',['a']),writeScopes:['a.txt']}],contract:{checks:[{id:'a',kind:'file.hash',target:'a.txt',args:{sha256:digest('final')}}]}},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>['integrated','paused'].includes(state(c,f.ctx).status));assert.equal(state(c,f.ctx).status,'integrated',state(c,f.ctx).error);assert.equal(git('rev-parse','HEAD'),head);assert.equal(git('diff','--cached'),'');assert.equal(readFileSync(join(f.project,'original.txt'),'utf8'),'user draft');assert.equal(state(c,f.ctx).attempts.every(a=>!a.commit),true);const artifacts=await c.dispatch('artifact.list',{graphId:g.id},f.ctx) as {artifacts:{stagingPath?:string;digest:string}[]};assert.ok(artifacts.artifacts.some(a=>a.digest===digest('first')&&readFileSync(a.stagingPath!,'utf8')==='first'));assert.equal(state(c,f.ctx).integration?.reviewStatus,'not_requested');
 }finally{await c.dispose();f.close();}
});

test('explicit required review runs for read-only V0; required contract cannot be waived or policy edited',async()=>{const f=fixture(),w=worker(),c=new SwarmController(w.launcher);try{await assert.rejects(c.dispatch('create',{goal:'cannot waive',tasks:[task('a')],executionPolicy:{review:'none'},contract:{verification:'V1'}},f.ctx),/不能关闭/);const g=await c.dispatch('create',{goal:'review required',tasks:[task('a')],executionPolicy:{v:1,workspace:'isolated',review:'required',dirtyBaseline:'reject'}},f.ctx) as Graph;await assert.rejects(c.dispatch('configure',{graphId:g.id,executionPolicy:{review:'none'}},f.ctx),/冻结/);await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>['integrated','paused'].includes(state(c,f.ctx).status));assert.equal(state(c,f.ctx).status,'integrated',state(c,f.ctx).error);assert.equal(w.starts.filter(s=>s.reviewResult).length,1);assert.equal(state(c,f.ctx).integration?.reviewStatus,'approved');}finally{await c.dispose();f.close();}});

test('per-spawn profile resolves before launch, explicit task model wins, snapshots are frozen and missing resources reject',async()=>{const f=fixture(),w=worker(),c=new SwarmController(w.launcher);f.ctx.availableModels=[{id:'fixture/test',thinkingLevels:['off']}];let received:JsonObject|undefined;const resolved={v:1,id:'arbitrary-expert',title:'custom',version:2,hash:'snapshot',prompt:'USER_PROFILE_PROMPT',skills:[{id:'skill',version:3,hash:'skill-hash',body:'FULL_SKILL_BODY'}],toolsMode:'allowlist',tools:[],modelId:'fixture/test',thinkingLevel:'off'};f.ctx.request=async(plugin,action,input)=>{if(plugin==='expert'&&action==='spawn.resolve'){received=input;const store=new RecordStore('expert',f.ctx.dataDir);try{new SourcePolicy(store).publishDependency({projectId:f.ctx.projectId,capability:'expert',id:`spawn:${resolved.hash}`,version:1,hash:resolved.hash,valid:true});}finally{store.close();}return structuredClone(resolved);}if(plugin==='expert'&&action==='spawn.validate')return {valid:true};throw new CapabilityError('CAPABILITY_UNAVAILABLE','optional plugin absent');};try{const g=await c.dispatch('create',{goal:'profile',tasks:[{...task('a'),expertId:'arbitrary-expert',expertOverrides:{prompt:'OVERRIDE',modelId:'unused/preset',toolsMode:'allowlist',tools:[]},modelId:'fixture/test',thinkingLevel:'off'}]},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>['integrated','paused'].includes(state(c,f.ctx).status));assert.equal(state(c,f.ctx).status,'integrated',state(c,f.ctx).error);assert.equal((received?.overrides as JsonObject).modelId,'fixture/test');assert.equal(w.starts[0].modelId,'fixture/test');assert.match(memberPrompt(w.starts[0]),/FULL_SKILL_BODY/);assert.deepEqual(w.starts[0].frozen?.resolvedExpert,resolved);resolved.prompt='mutated later';assert.equal(w.starts[0].frozen?.resolvedExpert?.prompt,'USER_PROFILE_PROMPT');}finally{await c.dispose();f.close();}});

test('claim citations bind each exact registered source and invalidate on revocation; observed unknown usage is not an estimate',async()=>{const f=fixture(),w=worker(),c=new SwarmController(w.launcher);const source={sessionId:'s',entryId:'e',hash:digest('source')};try{const checked=await c.dispatch('citations.validate',{claims:[{id:'c',claim:'traceable claim',sources:[source]}]},f.ctx) as {claims:{sourceDigests:string[]}[];entailmentVerified:boolean};const span=await c.dispatch('citations.validate',{claims:[{id:'span',claim:'span-bound',sources:[{sessionId:'s',entryId:'e',start:1,end:4}]}]},f.ctx) as {claims:{sources:{hash:string}[];sourceDigests:string[]}[]};assert.equal(span.claims[0].sources[0].hash,digest('our'));assert.deepEqual(span.claims[0].sourceDigests,[digest('our')]);assert.equal(checked.entailmentVerified,false);assert.deepEqual(checked.claims[0].sourceDigests,[digest('source')]);await assert.rejects(c.dispatch('citations.validate',{claims:[{id:'bad',claim:'no source',sources:[]}]},f.ctx),/已注册来源/);const g=await c.dispatch('create',{goal:'claim report',claims:[{id:'c',claim:'traceable claim',sources:[source]}],tasks:[task('a')],deferPreparation:true},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>state(c,f.ctx).status==='completed');const bound=await c.dispatch('citations.bind',{graphId:g.id,claims:[{id:'final',claim:'final result statement',sources:[source]}]},f.ctx) as Graph;assert.equal(bound.claims?.[0].id,'final');const summary=(c.snapshot(f.ctx) as {summaries:{elapsedMs:number;tokenUnknown:boolean;estimatedSavings:null}[]}).summaries[0];assert.ok(summary.elapsedMs>=0);assert.equal(summary.tokenUnknown,true);assert.equal(summary.estimatedSavings,null);const store=new RecordStore('host-policy',f.ctx.dataDir);try{new SourcePolicy(store).invalidate({projectId:'p',sources:[source],reason:'revoked',key:'revoke-claim'});}finally{store.close();}await c.dispatch('prepare',{graphId:g.id},f.ctx);await wait(()=>state(c,f.ctx).status==='paused');assert.equal(state(c,f.ctx).pauseReason?.code,'SOURCE_UNAVAILABLE');}finally{await c.dispose();f.close();}});

test('saved profile shadowing legacy ID resolves new bytes and missing explicit Skill fails before child creation',async()=>{for(const missing of [false,true]){const f=fixture(),w=worker(),c=new SwarmController(w.launcher);f.ctx.request=async(plugin,action)=>{if(plugin==='expert'&&action==='freeze')return {hash:'catalog',experts:[{id:'legacy',version:1,hash:'old',title:'old',prompt:'OLD'}],selectedIds:[]};if(plugin==='expert'&&action==='profile.read')return {source:'user'};if(plugin==='expert'&&action==='spawn.resolve'){if(missing)throw new CapabilityError('SOURCE_UNAVAILABLE','explicit Skill unavailable');const store=new RecordStore('expert',f.ctx.dataDir);try{new SourcePolicy(store).publishDependency({projectId:f.ctx.projectId,capability:'expert',id:'spawn:saved',version:1,hash:'saved',valid:true});}finally{store.close();}return {v:1,id:'legacy',title:'saved',version:2,hash:'saved',prompt:'SAVED_EDIT',skills:[],toolsMode:'inherit',tools:[],modelId:f.ctx.modelId};}if(plugin==='expert'&&action==='spawn.validate')return {valid:true};throw new CapabilityError('CAPABILITY_UNAVAILABLE','optional plugin absent');};try{const g=await c.dispatch('create',{goal:'saved profile',tasks:[{...task('a'),expertId:'legacy'}]},f.ctx) as Graph;await c.dispatch('start',{graphId:g.id},f.ctx);await wait(()=>['integrated','paused'].includes(state(c,f.ctx).status));if(missing){assert.equal(state(c,f.ctx).status,'paused');assert.equal(w.starts.length,0);}else{assert.equal(state(c,f.ctx).status,'integrated',state(c,f.ctx).error);assert.match(memberPrompt(w.starts[0]),/SAVED_EDIT/);assert.equal(w.starts[0].frozen?.resolvedExpert?.version,2);}}finally{await c.dispose();f.close();}}});
